<script setup lang="ts">
import type { Prediction, Json } from '../types'
import { percent, number, money, date } from '../format'
import StatusBadge from './StatusBadge.vue'
import { useKronosStore } from '../stores'
const kronos=useKronosStore()
defineProps<{ prediction: Prediction | null }>()
function object(v: Json | undefined) { return v && typeof v === 'object' && !Array.isArray(v) ? v : {} }
function numeric(v: Json | undefined) { return typeof v === 'number' ? v : typeof v === 'string' && v.trim() && Number.isFinite(Number(v)) ? Number(v) : null }
</script>
<template><section class="card signal-card"><div class="panel-heading"><div><span class="eyebrow">MOTOR DETERMINISTA</span><h3>Señal actual</h3></div><StatusBadge :value="prediction?.decision ?? 'INSUFFICIENT_EVIDENCE'" /></div><div class="prediction-highlight"><strong>{{ percent(prediction?.probability) }}</strong><span>Probabilidad estimada TP antes de SL<br><small>{{ prediction?.probabilityStatus ?? 'DATA_UNAVAILABLE' }}</small></span></div><dl class="detail-list"><dt>Dirección propuesta</dt><dd>{{ prediction?.direction ?? 'Sin señal' }}</dd><dt>Muestra comparable</dt><dd>{{ number(prediction?.sampleSize, 0) }}</dd><dt>Intervalo 95%</dt><dd>{{ percent(prediction?.lower95) }} — {{ percent(prediction?.upper95) }}</dd><dt>Régimen</dt><dd>{{ prediction?.regime ?? 'DATA_UNAVAILABLE' }}</dd><dt>Señal UTC/local</dt><dd>{{ date(prediction?.at) }}</dd></dl><div class="decision-row" v-for="(d, key) in prediction?.decisions ?? {}" :key="key"><b>{{ key }}</b><span>{{ object(d).reason ?? object(d).decision }}</span><small>EV: {{ object(d).expected_value ?? 'No evaluable' }} · EV conservador: {{ object(d).lower_bound_expected_value ?? 'No evaluable' }}</small><small>Target neto: {{ money(numeric(object(object(d).size).net_target)) }} · pérdida prevista: {{ money(numeric(object(object(d).size).risk)) }} · costos: {{ money(numeric(object(object(d).size).costs)) }} · reward/risk neto: {{ number(numeric(object(object(d).size).net_reward_risk)) }}</small></div><dl v-if="kronos.view?.latest" class="detail-list"><dt>Technical / Kronos</dt><dd>{{ kronos.view.latest.consensus.technical_signal ?? 'NO_SIGNAL' }} / {{ kronos.view.latest.consensus.kronos_direction }}</dd><dt>Raw TP / calibrated</dt><dd>{{ percent(kronos.view.latest.raw_tp_frequency) }} / {{ kronos.view.stale ? 'STALE' : percent(kronos.view.latest.calibrated_probability) }}</dd><dt>Consensus</dt><dd>{{ kronos.view.latest.consensus.consensus }}</dd><dt>Contradictions</dt><dd>{{ kronos.view.latest.consensus.disagreements.join(', ') || 'Sin contradicción registrada' }}</dd><dt>EV por perfil</dt><dd v-for="(v,p) in kronos.view.latest.consensus.economic_profiles" :key="p">{{ p }}: {{ money(v.expected_value) }}</dd></dl><p class="notice">Una estimación no es una certeza. Sol no genera la probabilidad ni puede omitir los filtros.</p></section></template>
